ps://www.zurgruenenhuette.com/","address":"Prater 196, 1020 Wien","latitude":48.21758,"longitude":16.40406},{"restaurant_id":"glashaus","display_name":"Das Glashaus","restaurant_type":"Österreichisch","phone":"+43 1 3483553","email":"hello@dasglashaus.at","opening_hours":["Mo–Mi 11:30–22:00","Do & Fr 11:30–23:00","Sa 09:00–23:00","So & Feiertag 09:00–15:00"],"contact_source":"https://www.dasglashaus.at/kontakt","menu_url":"https://www.dasglashaus.at/menues","website_url":"https://www.dasglashaus.at/","address":"Am Grünen Prater 11, 1020 Wien","latitude":48.2118847,"longitude":16.4120651},{"restaurant_id":"losteria","display_name":"L''Osteria","restaurant_type":"Italienisch","phone":"+43 1 720051010","email":"wien-wirtschaftsuni@losteria.at","opening_hours":["Mo–Mi & So 11:00–23:00","Do–Sa 11:00–00:00"],"contact_source":"https://losteria.net/de-en/restaurants/restaurant/wien-wirtschaftsuni/","menu_url":"https://losteria.net/at/menue/menu-della-casa/","website_url":"https://losteria.net/","address":"Freudplatz 2, 1020 Wien","latitude":48.21468,"longitude":16.4052}]'::jsonb) as x(restaurant_id text,display_name text,restaurant_type text,phone text,email text,opening_hours jsonb,contact_source text,menu_url text,website_url text,address text,latitude double precision,longitude double precision)) update public.restaurant_overrides p set display_name = coalesce(nullif(p.display_name,''),s.display_name),restaurant_type = coalesce(nullif(p.restaurant_type,''),s.restaurant_type),phone = coalesce(nullif(p.phone,''),s.phone),email = coalesce(nullif(p.email,''),s.email),opening_hours = coalesce(p.opening_hours,s.opening_hours),contact_source = coalesce(nullif(p.contact_source,''),s.contact_source),menu_url = coalesce(nullif(p.menu_url,''),s.menu_url),website_url = coalesce(nullif(p.website_url,''),s.website_url),address = coalesce(nullif(p.address,''),s.address),latitude = coalesce(p.latitude,s.latitude),longitude = coalesce(p.longitude,s.longitude) from seed s where p.restaurant_id=s.restaurant_id;